#!/usr/bin/env bash
# Check: the token stays a Secret that the Deployment refers to by name and
# key. It is not copied into a ConfigMap and not regenerated by Kustomize.
set -uo pipefail

fail=0
value="$(kubectl -n starfleet get secret scout-token -o json 2>/dev/null | jq -r '.data.token // "" | @base64d')"
if [ "$value" != "star-12345" ]; then
  echo "FAIL: the Secret scout-token is missing or its token changed"
  fail=1
fi

reference="$(kubectl -n starfleet get deployment scout -o json 2>/dev/null | jq -r '[.spec.template.spec.containers[] | select(.name=="scout") | .env[]? | select(.name=="SCOUT_TOKEN") | .valueFrom.secretKeyRef | "\(.name)/\(.key)"][0] // ""')"
if [ "$reference" != "scout-token/token" ]; then
  echo "FAIL: SCOUT_TOKEN refers to '$reference', expected a secretKeyRef to scout-token/token"
  fail=1
fi

leaks="$(kubectl -n starfleet get configmaps -o json 2>/dev/null | jq '[.items[] | select((.data // {}) | to_entries | any(.value | tostring | contains("star-12345")))] | length')"
if [ "$leaks" != "0" ]; then
  echo "FAIL: a ConfigMap in starfleet contains the token value"
  fail=1
fi

other="$(kubectl -n starfleet get secrets -o json 2>/dev/null | jq '[.items[] | select(.metadata.name | startswith("scout-token-"))] | length')"
if [ "$other" != "0" ]; then
  echo "FAIL: a generated Secret scout-token-<hash> exists, the Secret must stay as it is"
  fail=1
fi

if [ "$fail" -eq 0 ]; then
  echo "PASS: SCOUT_TOKEN refers to the existing Secret and no ConfigMap holds the value"
fi
exit "$fail"
